&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Sahuagin&lt;div style=&quot;float:right;&quot;&gt;FP 2&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de monstrueux&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de monstrueux.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Aquatique&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Aquatique.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire&lt;/i&gt; p.251
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 600
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de-Monstrueux.html&quot; title=&quot;Humano&#239;de monstrueux&quot;&gt;Humano&#239;de monstrueux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Aquatique.html&quot; title=&quot;Aquatique (sous-type)&quot;&gt;aquatique&lt;/a&gt;) de taille M, LM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +1 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;perception aveugle&quot;&gt;perception aveugle&lt;/a&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +6
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 16, contact 11, pris au d&#233;pourvu 15 (Dex +1, naturelle +5)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 15 (2d10+4)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +4, &lt;b&gt;Vig&lt;/b&gt; +4, &lt;b&gt;Vol&lt;/b&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Faiblesses&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Aveugl&#233;-Par-La-Lumi&#232;re-(Capacit&#233;).html&quot; title=&quot;Aveugl&#233; par la lumi&#232;re&quot;&gt;aveugl&#233; par la lumi&#232;re&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), nage 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; trident, +4 (1d8+3), morsure, -1 (1d4+1) ou 2 griffes, +4 (1d4+2), morsure, +4 (1d4+2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; arbal&#232;te lourde, +3 (1d10/19-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; fr&#233;n&#233;sie inspir&#233;e par le sang
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 14, &lt;b&gt;Dex&lt;/b&gt; 13, &lt;b&gt;Con&lt;/b&gt; 14, &lt;b&gt;Int&lt;/b&gt; 14, &lt;b&gt;Sag&lt;/b&gt; 13, &lt;b&gt;Cha&lt;/b&gt; 9
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +2, &lt;b&gt;BMO&lt;/b&gt; +4, &lt;b&gt;DMD&lt;/b&gt; 15
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vigueur-Surhumaine.html&quot; title=&quot;Vigueur surhumaine&quot;&gt;Vigueur surhumaine&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +15, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +6
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; aquatique, commun ; communication avec les requins
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; oc&#233;ans temp&#233;r&#233;s ou chauds
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire, couple, &#233;quipe (5-8), patrouille (11-20 et 1 lieutenant de niveau 3 et 1-2 &lt;a class=&quot;pagelink&quot; href=&quot;Requin.html&quot; title=&quot;Requin&quot;&gt;requins&lt;/a&gt;), bande (20-80 et 100% de non combattants et 1 lieutenant de niveau 3 et 1 chef de niveau 4 par 20 adultes et 1-2 &lt;a class=&quot;pagelink&quot; href=&quot;Requin.html&quot; title=&quot;Requin&quot;&gt;requins&lt;/a&gt;) ou tribu (70-160 et 100% de non combattants, 1 lieutenant de niveau 3 par 20 adultes, 1 chef de niveau 4 par 40 adultes, 9 gardes de niveau 4, 1-4 sous pr&#234;tresses de niveau 3-6, 1 pr&#234;tresse de niveau 7, 1 baron de niveau 6-8 et 5-8 &lt;a class=&quot;pagelink&quot; href=&quot;Requin.html&quot; title=&quot;Requin&quot;&gt;requins&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; &#233;quipement de PNJ (arbal&#232;te lourde avec 10 carreaux, trident, autres tr&#233;sors)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Capacit&#233;s sp&#233;ciales&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Communication avec les requins (Sur)&lt;/b&gt; Les sahuagins peuvent communiquer par &lt;a class=&quot;pagelink&quot; href=&quot;T&#233;l&#233;pathie-(Capacit&#233;).html&quot; title=&quot;T&#233;l&#233;pathie&quot;&gt;t&#233;l&#233;pathie&lt;/a&gt; avec les &lt;a class=&quot;pagelink&quot; href=&quot;Requin.html&quot; title=&quot;Requin&quot;&gt;requins&lt;/a&gt; dans un rayon de 45 m&#232;tres (30 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;). L&#39;&#233;change se limite &#224; des concepts simples tels que &quot;viens ici,&quot; &quot;prot&#232;ge-moi&quot; ou &quot;attaque cette cible&quot;.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Fr&#233;n&#233;sie inspir&#233;e par le sang (Ext)&lt;/b&gt; Une fois par jour, lorsqu&#39;un sahuagin est bless&#233; au cours d&#39;un combat, il peut se laisser gagner par la fr&#233;n&#233;sie d&#232;s que son tour arrive. Il gagne un bonus de +2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; mais subit un malus de -2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. La fr&#233;n&#233;sie persiste pendant 1 minute ou seulement jusqu&#39;&#224; la fin du combat si celui-ci se termine avant.
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;i&gt;Cet humano&#239;de &#233;cailleux a des dents ac&#233;r&#233;es, une longue queue de poisson
et des bras et des jambes termin&#233;es par des griffes palm&#233;es.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les cruels et voraces sahuagins figurent malheureusement parmi
les plus prosp&#232;res des races qui habitent les oc&#233;ans. Les fosses
sous-marines sont parsem&#233;es de grandes cit&#233;s construites par
ces cr&#233;atures. Celles qui se trouvent pr&#232;s de la c&#244;te servent de
forteresses &#224; partir desquelles les sahuagins lancent d’incessantes
attaques contre leurs ennemis qui vivent hors de l’eau, sur le rivage.
Ces fiers guerriers ne s’allient que tr&#232;s rarement avec d’autres races
et consid&#232;rent la plupart des cr&#233;atures aquatiques (les aboleths, les
hommes-poissons et toute autre cr&#233;ature apparent&#233;e) comme des
concurrents. Les requins sont les seules cr&#233;atures qu’ils respectent
et adorent en dehors d’eux-m&#234;mes, car ils se trouvent beaucoup de
points communs avec ces pr&#233;dateurs implacables. Un sahuagin
mesure 2,10 m&#232;tres de hauteur et p&#232;se &#224; peu pr&#232;s 125 kg.&lt;br /&gt;&lt;br /&gt;Les mutations b&#233;n&#233;fiques sont assez courantes chez les sahuagins
et les individus qui naissent avec une telle mutation deviennent
presque toujours des nobles ou des dirigeants au sein de leur
soci&#233;t&#233;. La mutation la plus r&#233;pandue prend la forme d’une paire
de bras suppl&#233;mentaire (ce qui leur donne deux attaques de griffes
additionnelles ou la capacit&#233; de manier plus d’armes). Certaines
rumeurs parlent de malentis, des sahuagins qui ressemblent &#224;
des elfes aquatiques plut&#244;t qu’&#224; des hommes-requins mais qui
poss&#232;dent la soif de combat et la cruaut&#233; de leurs fr&#232;res. Les malentis
remplissent souvent le r&#244;le d’espions ou d’assassins au service des
dirigeants sahuagins mais, selon la rumeur, il existerait des tribus
exclusivement compos&#233;es de
malentis dans des recoins isol&#233;s de
la mer.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;&#201;cologie&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;cologie_2&quot; href=&quot;#&#201;cologie_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les sahuagins sont d’horribles cr&#233;atures qui sillonnent les oc&#233;ans, toujours pr&#234;tes &#224; semer la destruction. Ces &#171; diables des mers &#187; d&#233;pouillent les navires de tout leur &#233;quipage puis les laissent d&#233;river, ils ravissent des villages entiers au milieu de la nuit et ils forcent les elfes aquatiques et hommes-poissons &#224; partir en guerre.&lt;br /&gt;&lt;br /&gt;Les sahuagins sont des &#234;tres complexes &#224; l’intelligence vive, qui ont d&#233;sesp&#233;r&#233;ment besoin d’ordre et de structure mais qui bouillonnent d’une rage et d’une soif de sang &#224; peine contenues. La moindre petite provocation peut transformer le sahuagin le plus froid et calculateur en un meurtrier violent. Afin de garder leur sang-froid et de rester alertes en p&#233;riode de crise, les sahuagins se pr&#233;lassent p&#233;riodiquement dans des eaux macul&#233;es de sang (ceux qui ne parviennent pas &#224; &#233;tancher leur soif de sang plongent dans une l&#233;thargie apathique ou craquent et se retournent contre les leurs).&lt;br /&gt;&lt;br /&gt;En tant que peuple, les sahuagins ne cherchent rien de moins que la domination totale des mers. Bien qu’ils adorent d&#233;cha&#238;ner la destruction sur les esp&#232;ces intelligentes, les sahuagins sont aussi en guerre perp&#233;tuelle contre les leurs. Leurs rois et reines encouragent ces vendettas sanglantes et mesquines, y voyant un moyen de satisfaire la fr&#233;n&#233;sie de sang qui caract&#233;rise ces cr&#233;atures ainsi que de contr&#244;ler leur nombre et de parfaire un peu plus les talents d&#233;j&#224; consid&#233;rables de cette race pour le combat.&lt;br /&gt;&lt;br /&gt;Contrairement &#224; la plupart des humano&#239;des aquatiques, les sahuagins se plaisent dans la mer, quelle que soit la profondeur ou la temp&#233;rature. M&#234;me ainsi, ils manifestent cependant une pr&#233;f&#233;rence marqu&#233;e pour les eaux littorales chaudes – peut-&#234;tre &#224; cause de l’abondance de nourriture et de cr&#233;atures &#224; terroriser qu’ils peuvent y trouver. On trouve les sahuagins partout, des atolls abrit&#233;s aux fosses les plus noires en passant par les tropiques ou les p&#244;les. Ils se sont m&#234;me &#233;tendus au plan &#233;l&#233;mentaire de l’Eau.&lt;br /&gt;&lt;br /&gt;L’existence des sahuagins r&#233;pond &#224; un syst&#232;me f&#233;odal, incarnation d’une ex&#233;cution impitoyable de l’ordre. Chaque sahuagin a sa propre position, qu’il doit &#224; ses prouesses et &#224; ses comp&#233;tences, mais peut se voir r&#233;trograd&#233; s’il montre le moindre signe d’incomp&#233;tence (quand il n’est pas mis &#224; mort pour avoir manifest&#233; sa faiblesse). Les officiers et les seigneurs r&#232;gnent sur des domaines mineurs, vassaux des barons, des ducs et des princesses ; les rois et les reines, quant &#224; eux, gouvernent des oc&#233;ans entiers depuis leur grand palais, qui si&#232;ge au sein de cit&#233;s grouillant de dizaines de milliers de sujets. Chaque noble sahuagin cherche &#224; soumettre les autres &#224; sa volont&#233; pour devenir le seigneur de son propre empire oc&#233;anique, s’effor&#231;ant de pr&#233;cipiter l’&#226;ge de la domination sahuagin.&lt;br /&gt;&lt;br /&gt;Malgr&#233; les titres de noblesse qu’ils utilisent, les sahuagins n’accordent gu&#232;re de valeur aux lign&#233;es. La r&#233;ussite l’emporte sur la parent&#233; et, si les sahuagins s’enorgueillissent de compter certains membres de leur famille qui jouissent d’une certaine force et influence, m&#234;me les rejetons de la royaut&#233; doivent faire leurs preuves et se d&#233;brouiller par eux-m&#234;mes. Certains de ces enfants ont davantage d’opportunit&#233;s que les autres mais la fille ambitieuse d’un simple ouvrier pourra se hisser au rang de baronne l&#224; o&#249; le fils inepte d’un baron n’est pas &#224; l’abri de servir de pitance &#224; meilleur que lui.&lt;br /&gt;&lt;br /&gt;Les sahuagins ne consid&#232;rent les autres cr&#233;atures qu’&#224; travers le spectre de leur app&#233;tit : les autres races n’existent que pour leur servir d’esclaves, pour mourir dans les ar&#232;nes ou au combat, ou pour nourrir les sahuagins. Ces monstres s’allient rarement aux autres cr&#233;atures que leurs requins ador&#233;s et qu’aux adaros B3, apparent&#233;s aux requins, bien qu’il leur arrive parfois d’asservir un dragon-tortue et d’autres monstres aquatiques terrifiants en tant que b&#234;tes de guerre. Ils n’&#233;prouvent que du m&#233;pris pour les elfes aquatiques, les locathahs B2, les hommes-poissons et les tritons B2, les consid&#233;rant comme des faibles juste bons &#224; &#234;tre r&#233;duits en esclavage et &#224; satisfaire leur app&#233;tit. Les aboleths et les krakens, quant &#224; eux, ont droit &#224; un peu plus de respect, m&#234;l&#233; d’un profond d&#233;go&#251;t, parce qu’ils sont le plus grand obstacle s&#233;parant les sahuagins de leur volont&#233; de dominer les mers.&lt;br /&gt;&lt;br /&gt;Les jeunes sahuagins sont issus de couv&#233;es pouvant compter jusqu’&#224; deux cents œufs, que les femelles pondent dans des chambres tr&#232;s bien prot&#233;g&#233;es. Une seule colonie de sahuagins compte en g&#233;n&#233;ral une chambre, mais les grandes cit&#233;s peuvent en accueillir une douzaine. Les œufs &#233;closent trois mois apr&#232;s la ponte, crachant des alevins qui ressemblent &#224; des anguilles et sont tout en crocs, en m&#226;choire et en queue. L’&#233;closion g&#233;n&#232;re une violente fr&#233;n&#233;sie puisque les nouveau-n&#233;s d&#233;vorent les membres les plus petits et les plus faibles de la port&#233;e. Nombre des survivants succombent &#224; de plus grands pr&#233;dateurs ou se font d&#233;vorer par leurs a&#238;n&#233;s quand, pass&#233; leur premier repas brutal, ceux-ci ressentent &#224; nouveau la faim. Seuls les plus fut&#233;s, les plus rapides ou les plus forts survivent au sein de ces &#233;closeries.&lt;br /&gt;&lt;br /&gt;Les parents sahuagins reviennent r&#233;cup&#233;rer les petits survivants au bout d’un an, reconnaissant leur prog&#233;niture &#224; l’odeur. Certains petits restent orphelins, leurs parents ayant p&#233;ri ou &#233;tant incapables de pister leur odeur. Les baraquements sahuagins permettent d’&#233;lever ces jeunes en communaut&#233;, o&#249; ils sont envoy&#233;s au combat d&#232;s qu’ils sont en mesure de manier un trident.&lt;br /&gt;&lt;br /&gt;Les sahuagins atteignent tr&#232;s vite l’&#226;ge adulte, d&#233;veloppant des bras et des jambes aux alentours de six mois, mesurant pr&#232;s d’un m&#232;tre cinquante en l’espace d’un an et atteignant leur taille adulte, de deux m&#232;tres dix, au cours de leur sixi&#232;me ann&#233;e. Quand ils deviennent adultes, les sahuagins du bas de l’&#233;chelle sociale doivent se d&#233;brouiller par eux-m&#234;mes s’ils ne veulent pas mourir – ceux qui sont situ&#233;s plus haut dans l’&#233;chelle sociale sont souvent form&#233;s et prot&#233;g&#233;s suffisamment longtemps par leurs parents pour devenir des guerriers talentueux et redoutables.&lt;br /&gt;&lt;br /&gt;En tant qu’esp&#232;ce, les sahuagins sont particuli&#232;rement sujets &#224; la mutation (voir plus bas). La plupart des mutants p&#233;rissent dans les &#233;closeries mais ceux qui survivent jouissent tr&#232;s t&#244;t d’un certain respect, leurs &#233;tranges capacit&#233;s &#233;tant consid&#233;r&#233;es comme une preuve de faveur divine. Les mutants les plus courants sont les terribles sahuagins &#224; quatre bras, qui repr&#233;sentent environ un jeune survivant sur cent. D’autres mutations apparaissent en fonction des conditions environnementales ou de la proximit&#233; des autres esp&#232;ces, ou sont parfois le r&#233;sultat de traces de polluants dans l’eau. On compte tout particuli&#232;rement les malenti, des sahuagins qui, pour des raisons inconnues, ressemblent trait pour trait &#224; des elfes aquatiques d&#232;s la naissance.&lt;br /&gt;&lt;br /&gt;Les sahuagins jouissent d’une esp&#233;rance de vie tr&#232;s longue, peut-&#234;tre m&#234;me illimit&#233;e, mais la plupart d’entre eux se font faucher dans la violence avant m&#234;me d’atteindre leur trenti&#232;me anniversaire. Certains princes et reines particuli&#232;rement f&#233;roces r&#232;gnent n&#233;anmoins pendant plusieurs centaines d’ann&#233;es vu que le corps des sahuagins ne se fl&#233;trit pas avec le temps. Les sahuagins exceptionnellement vieux sont nettement plus grands que les plus jeunes (ils deviennent des cr&#233;atures de taille G avec l’&#226;ge). Mais, quel que soit leur &#226;ge, tous les sahuagins m&#233;prisent l’infirmit&#233; et tentent d’en exciser tous les exemples de leurs rangs, r&#233;agissant avec une violence atavique &#224; tout signe de faiblesse.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Sahuagins mutants&lt;a class=&quot;headeranchor&quot; id=&quot;Sahuagins_mutants_3&quot; href=&quot;#Sahuagins_mutants_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;L’instabilit&#233; inh&#233;rente aux g&#232;nes sahuagins fait que ces cr&#233;atures sont sujettes aux mutations. Toutes ces mutations ne sont pas b&#233;n&#233;fiques et les sahuagins d&#233;ficients survivent rarement bien longtemps apr&#232;s l’&#233;closion. Les sahuagins mutants qui parviennent &#224; survivre et atteignent l’&#226;ge adulte forcent le respect et l’admiration de leurs pairs, se hissant tr&#232;s vite &#224; des positions de pouvoir. Les sahuagins &#224; quatre bras et les malentis sont les sahuagins mutants les plus courants.
&lt;div class=&quot;row Ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Malenti.&lt;/b&gt; Les malentis ressemblent &#224; des elfes aquatiques et re&#231;oivent un bonus de +4 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;, ainsi que les dons suppl&#233;mentaires &lt;a class=&quot;pagelink&quot; href=&quot;Fourberie.html&quot; title=&quot;Fourberie&quot;&gt;Fourberie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Bluff). Ils peuvent utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Injonction.html&quot; title=&quot;Injonction&quot;&gt;injonction&lt;/a&gt;&lt;/i&gt; comme un pouvoir magique trois fois par jour (ce pouvoir ne fonctionne que sur les cr&#233;atures de sous-type aquatique, illustrant ainsi l’influence t&#233;l&#233;pathique des sahuagins sur les cr&#233;atures aquatiques). En outre, le bonus d’armure naturelle des malentis est r&#233;duit &#224; +2 et ils perdent leur particularit&#233; aveugl&#233; par la lumi&#232;re et leurs armes naturelles. Les malentis excellent comme &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;bardes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Oracle.html&quot; title=&quot;L&amp;#39;oracle&quot;&gt;oracles&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublards&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magiciens&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sahuagin &#224; quatre bras.&lt;/b&gt; Ces mutants sont dot&#233;s de quatre bras qui leur apportent deux attaques de griffe suppl&#233;mentaires. Ils gagnent les dons suppl&#233;mentaires d’&lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, ainsi que le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Du-Combat-&#192;-Plusieurs-Armes-(Capacit&#233;).html&quot; title=&quot;Ma&#238;trise du combat &#224; plusieurs armes (Ext)&quot;&gt;ma&#238;trise du combat &#224; plusieurs armes&lt;/a&gt;. Ils ont un &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de base de 3 et excellent comme &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbares&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerriers&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deurs&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sahuagin aveugle.&lt;/b&gt; Ces sahuagins blafards &#224; l’air malade n’ont pas d’yeux mais la port&#233;e de leur &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; passe &#224; 27 m&#232;tres et ils gagnent le don suppl&#233;mentaire &lt;a class=&quot;pagelink&quot; href=&quot;Combat-En-Aveugle.html&quot; title=&quot;Combat en aveugle&quot;&gt;Combat en aveugle&lt;/a&gt;. Les sahuagins aveugles sont dot&#233;s d’un tentacule scintillant qui &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;bloui.html&quot; title=&quot;&#201;bloui&quot;&gt;&#233;blouit&lt;/a&gt; toutes les cr&#233;atures dou&#233;es de la vue dans un rayon de 3 m&#232;tres et qui leur permet d’utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hypnose-Des-Animaux.html&quot; title=&quot;Hypnose des animaux&quot;&gt;hypnose des animaux&lt;/a&gt;&lt;/i&gt; une fois par jour comme un pouvoir magique. L’effet de ce pouvoir est enti&#232;rement visuel et n’appartient nullement au registre du son ni ne fonctionne sur les cr&#233;atures aveugles. Comme ces sahuagins sont aveugles, ils sont immunis&#233;s contre tous les effets et toutes les attaques bas&#233;s sur la vue, y compris contre les &lt;a class=&quot;pagelink&quot; href=&quot;Regard-(Capacit&#233;).html&quot; title=&quot;Regard (Sur)&quot;&gt;attaques de regard&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Sahuagin &#233;pineux.&lt;/b&gt; Couvert de centaines d’&#233;pines semblables &#224; des aiguilles, le sahuagin &#233;pineux peut d&#233;ployer ses pointes perforantes pour empaler les cr&#233;atures qui le touchent. Toutes les cr&#233;atures qui &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Agripp&#233;.html&quot; title=&quot;Agripp&#233;&quot;&gt;agrippent&lt;/a&gt; ou se font agripper par un sahuagin &#233;pineux, ou en touchent un &#224; mains nues ou avec une arme naturelle, re&#231;oivent 1d4 points de d&#233;g&#226;ts perforants. En outre, ces mutants gagnent les dons suppl&#233;mentaires &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Du-Combat-D&#233;fensif.html&quot; title=&quot;Ma&#238;trise du combat d&#233;fensif&quot;&gt;Ma&#238;trise du combat d&#233;fensif&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-La-Lutte.html&quot; title=&quot;Science de la lutte&quot;&gt;Science de la lutte&lt;/a&gt;. Les sahuagins &#233;pineux vivent g&#233;n&#233;ralement dans les profondeurs qui leur servent &#233;galement de terrain de chasse contre les serpents de mer, les &lt;a class=&quot;pagelink&quot; href=&quot;B&#233;h&#233;moth-Thalassique.html&quot; title=&quot;B&#233;h&#233;moth thalassique&quot;&gt;b&#233;h&#233;moths thalassiques&lt;/a&gt; ou les autres &#233;normes pr&#233;dateurs aquatiques.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sahuagin pr&#233;historique.&lt;/b&gt; Aussi appel&#233;s les adacthys, ces sahuagins mutants renvoient &#224; une &#233;poque plus sauvage. Ce sont des cr&#233;atures de taille G avec un bonus d’armure naturelle de +7, qui peuvent communiquer avec les dinosaures et la m&#233;gafaune aquatiques en plus des requins. Les adacthys peuplent g&#233;n&#233;ralement les m&#234;mes eaux que les cr&#233;atures pr&#233;historiques.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sahuagin requin.&lt;/b&gt; Ces sahuagins mutants sont pourvus de m&#226;choires impressionnantes remplies de rang&#233;es de dents de requin, ainsi que de nageoires et d’une queue de requin g&#233;ant. Ces anomalies leur donnent l’apparence d’&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;hommes-poissons&lt;/a&gt; monstrueux, une vitesse de base de 1,50 m&#232;tre, une vitesse de nage de 24 m&#232;tres, une attaque de morsure infligeant 1d6 points de d&#233;g&#226;ts et une immunit&#233; contre les tentatives de &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt;. Les sahuagins requins vivent g&#233;n&#233;ralement dans les communaut&#233;s de sahuagins comptant un nombre exceptionnellement &#233;lev&#233; de gardiens requins ou &#224; proximit&#233; des zones de reproduction des requins.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_4&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les r&#232;gles suivantes illustrent une large vari&#233;t&#233; de sahuagins.
&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_0&quot; href=&quot;#Dons_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici quelques dons tr&#232;s appr&#233;ci&#233;s des sahuagins.
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot; WIDTH=&quot;100%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;37%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Avantage-Aquatique.html&quot; title=&quot;Avantage aquatique&quot;&gt;Avantage aquatique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, vitesse de nage naturelle&lt;/td&gt;&lt;td&gt;Les cr&#233;atures qui n&#39;ont pas de vitesse de nage provoquent des attaques d&#39;opportunit&#233; lorsqu&#39;elles attaquent le personnage&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fr&#233;n&#233;sie-Du-Sang-Sup&#233;rieure.html&quot; title=&quot;Fr&#233;n&#233;sie du sang sup&#233;rieure&quot;&gt;Fr&#233;n&#233;sie du sang sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Sahuagin.html&quot; title=&quot;Sahuagin&quot;&gt;fr&#233;n&#233;sie inspir&#233;e par le sang&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sahuagin.html&quot; title=&quot;Sahuagin&quot;&gt;sahuagin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Pas de malus &#224; la CA et gain du pouvoir &#233;ventration lorsque la fr&#233;n&#233;sie inspir&#233;e par le sang est active&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Mar&#233;e-De-Sang.html&quot; title=&quot;Mar&#233;e de sang&quot;&gt;Mar&#233;e de sang&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Expertise-Du-Combat.html&quot; title=&quot;Expertise du combat&quot;&gt;Expertise du combat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Fr&#233;n&#233;sie-Du-Sang-Sup&#233;rieure.html&quot; title=&quot;Fr&#233;n&#233;sie du sang sup&#233;rieure&quot;&gt;Fr&#233;n&#233;sie du sang sup&#233;rieure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Sahuagin.html&quot; title=&quot;Sahuagin&quot;&gt;sahuagin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Abandonne les attaques normales pour en obtenir plus contre tous les adversaires bless&#233; qui saignent&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
&lt;div class=&quot;row ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_1&quot; href=&quot;#Sorts_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les sahuagins choisissent des sorts qui am&#233;liorent leurs dons naturels.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Eau-Rouge.html&quot; title=&quot;Eau rouge&quot;&gt;Eau rouge&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(CM)&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;Hyp 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;Pr&#234; 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy 2&lt;/a&gt;). Conf&#232;re la fr&#233;n&#233;sie inspir&#233;e par le sang aux cr&#233;atures dans la zone.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Don-Des-Profondeurs.html&quot; title=&quot;Don des profondeurs&quot;&gt;Don des profondeurs&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(CM)&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag 5&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;Pr&#234; 4&lt;/a&gt;). Conf&#232;re des pouvoirs uniques aux mutants au sahuagin cibl&#233;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Respiration-Dair.html&quot; title=&quot;Respiration d&amp;#39;air&quot;&gt;Respiration d&#39;air&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(CM)&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alch 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Chaman.html&quot; title=&quot;Le chaman&quot;&gt;Cham 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;Con 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;Dru 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;Magus 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;Pr&#234; 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy 3&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;San 3&lt;/a&gt;). Permet aux cibles de respirer l&#39;air.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;/div&gt;
